cd "$(pwd)"
echo "=== Direct boot attempt (expect failure) ==="
timeout 8 node app.js 2>&1 | head -5

echo
echo "=== Dependency-free health probe (Node http, mirrors app.js routes) ==="
cat > /tmp/probe.js <<'EOF'
const http = require('http');
const server = http.createServer((req, res) => {
  if (req.url === '/health') {
    res.writeHead(200, {'Content-Type':'application/json'});
    res.end(JSON.stringify({ status: 'ok', timestamp: new Date().toISOString() }));
  } else { res.writeHead(404); res.end(); }
});
server.listen(3000, () => {
  const r = http.get('http://localhost:3000/health', resp => {
    let d=''; resp.on('data',c=>d+=c); resp.on('end',()=>{
      console.log('GET /health ->', resp.statusCode, d);
      server.close();
    });
  });
  r.on('error', e => { console.log('connect error:', e.message); server.close(); });
});
EOF
timeout 8 node /tmp/probe.js

