echo "=== Is anything listening on port 3000? ===";
(ss -ltnp 2>/dev/null | grep ':3000' || netstat -ltnp 2>/dev/null | grep ':3000' || lsof -iTCP:3000 -sTCP:LISTEN 2>/dev/null) || echo "Nothing listening on :3000";
echo;
echo "=== node processes ===";
ps aux | grep -i '[n]ode' || echo "No node process found";
echo;
echo "=== Probe /health endpoint ===";
curl -sS -m 5 -o - -w "\nHTTP_STATUS:%{http_code}\n" http://localhost:3000/health 2>&1 || echo "curl failed (service not reachable)"

echo "=== Probe a few routes to fingerprint the responder ===";
for p in /health /users /; do
  echo "--- GET $p ---";
  curl -sS -m 5 -D - -o /tmp/body http://localhost:3000$p 2>&1 | sed -n '1,8p';
  echo "body: $(cat /tmp/body)";
  echo;
done
echo "=== Try to actually start acme-service ===";
node -e "require('./app.js')" & sleep 1;
curl -sS -m 5 -w "\nHTTP_STATUS:%{http_code}\n" http://localhost:3000/health 2>&1;
kill %1 2>/dev/null

